function render(){frame++;let camX=Math.floor(player.x*T-W/2),camY=Math.floor(player.y*T-H/2);camX=Math.max(0,Math.min(MAPW*T-W,camX));camY=Math.max(0,Math.min(MAPH*T-H,camY));let sx=Math.floor(camX/T),sy=Math.floor(camY/T),ox=-(camX%T),oy=-(camY%T);for(let yy=0;yy<Math.ceil(H/T)+1;yy++)for(let xx=0;xx<Math.ceil(W/T)+1;xx++)drawTile(sx+xx,sy+yy,xx+ox/T,yy+oy/T);
