ctx.strokeStyle='#ffffff24';ctx.lineWidth=1;ctx.strokeRect(0,0,W,H);document.getElementById('coords').textContent=`X ${String(Math.floor(player.x)).padStart(3,'0')} · Y ${String(Math.floor(player.y)).padStart(3,'0')}`;requestAnimationFrame(render)}
function tell(text){const n=document.getElementById('notice');n.textContent=text;n.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.classList.remove('show'),2100)}
function move(dir){if(encounter)return;player.dir=dir;let dx=dir==='left'?-1:dir==='right'?1:0,dy=dir==='up'?-1:dir==='down'?1:0,nx=Math.max(1,Math.min(MAPW-2,player.x+dx*.6)),ny=Math.max(1,Math.min(MAPH-2,player.y+dy*.6));let terrain=tile(Math.floor(nx),Math.floor(ny)).kind;if(['water','tree','rock'].includes(terrain)){return}player.x=nx;player.y=ny;player.steps++;if(player.steps%3===0)save();if(terrain==='grass'&&Math.random()<.23)startEncounter();else if(player.steps%17===0){const b=biome(nx,ny);document.getElementById('worldHint').textContent=b==='MEADOW'?'The meadow hums softly in the breeze.':b==='FROST'?'A quiet chill settles over the snowfields.':b==='DUSK'?'Something glimmers in the dusky woods.':'The flowers here seem to sparkle.'}}
window.addEventListener('keydown',e=>{let d={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'}[e.key];if(d){e.preventDefault();if(!keys[e.key])move(d);keys[e.key]=true}if(e.key==='Escape'){closeOverlays()}});window.addEventListener('keyup',e=>{delete keys[e.key]});setInterval(()=>{for(let k in keys){let d={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'}[k];if(d)move(d)}},145);
document.querySelectorAll('.mobile-pad button').forEach(b=>{let timer;const start=e=>{e.preventDefault();move(b.dataset.dir);timer=setInterval(()=>move(b.dataset.dir),150)},stop=()=>clearInterval(timer);b.addEventListener('pointerdown',start);b.addEventListener('pointerup',stop);b.addEventListener('pointerleave',stop)});
document.getElementById('zoomIn').onclick=()=>{zoom=Math.min(1.5,zoom+.1);tell('You lean in for a closer look!')};document.getElementById('zoomOut').onclick=()=>{zoom=Math.max(.7,zoom-.1);tell('You take in the wide open wilds!')};
function startEncounter(){let b=biome(player.x,player.y),pool=species.filter(s=>s.type===b||b==='MEADOW'&&s.type==='MEADOW');if(b==='MEADOW')pool=species.filter(s=>['MEADOW','MYSTIC'].includes(s.type));let c={...pool[Math.floor(Math.random()*pool.length)]};c.maxHp=c.hp;c.level=1+Math.floor(Math.random()*4);c.hp=c.maxHp;encounter=c;seen.add(c.name);save();document.getElementById('enemyName').textContent=c.name;document.getElementById('enemyLvl').textContent='Lv. '+c.level;document.getElementById('enemyHp').style.width='100%';document.getElementById('battleMsg').textContent=`A wild ${c.name} is watching you! Maybe it would like a berry?`;document.getElementById('battleOverlay').classList.add('open');drawBattle();updateUI()}
const bctx=document.getElementById('battleCanvas').getContext('2d');function drawBattle(){bctx.imageSmoothingEnabled=false;bctx.clearRect(0,0,560,220);bctx.fillStyle='#e6eedb';bctx.fillRect(0,0,560,220);bctx.fillStyle='#d5e5c4';bctx.fillRect(0,135,560,85);bctx.fillStyle='#a8c887';bctx.fillRect(40,143,150,15);bctx.fillRect(354,105,150,15);bctx.fillStyle='#f8f2d5';bctx.fillRect(55,145,120,10);bctx.fillRect(372,107,120,9);if(encounter)drawCreature(encounter,430,89,4,.2);drawCreature({color:'#78a6a2',accent:'#e9d598',shape:0},120,132,3,.1);for(let i=0;i<15;i++){let x=(i*57+19)%560,y=(i*31+22)%150;bctx.fillStyle=i%2?'#f8eab3':'#d5e0b2';bctx.fillRect(x,y,2,2)}}
function closeEncounter(msg){document.getElementById('battleMsg').textContent=msg;document.querySelectorAll('.battle-actions button').forEach(x=>x.disabled=true);setTimeout(()=>{document.getElementById('battleOverlay').classList.remove('open');document.querySelectorAll('.battle-actions button').forEach(x=>x.disabled=false);encounter=null;updateUI();save()},1050)}
document.getElementById('catchBtn').onclick=()=>{if(!encounter)return;let chance=.44+(1-encounter.hp/encounter.maxHp)*.5;if(Math.random()<chance){if(team.length<6){team.push({name:encounter.name,type:encounter.type,color:encounter.color,accent:encounter.accent,shape:encounter.shape,level:encounter.level});closeEncounter(`${encounter.name} joined your little expedition!`)}else closeEncounter(`${encounter.name} is already in your field guide. Your team is full!`)}else{document.getElementById('battleMsg').textContent=`${encounter.name} gave the berry a sniff, then bounced away!`;setTimeout(()=>{if(encounter){document.getElementById('battleMsg').textContent=`${encounter.name} is still curious... try a gentle boop first!`}},750)}};
document.getElementById('battleAttack').onclick=()=>{if(!encounter)return;encounter.hp=Math.max(1,encounter.hp-6-Math.floor(Math.random()*5));document.getElementById('enemyHp').style.width=(encounter.hp/encounter.maxHp*100)+'%';document.getElementById('battleMsg').textContent=`A gentle boop! ${encounter.name} looks a little wobbly.`;if(encounter.hp<=4)document.getElementById('battleMsg').textContent=`${encounter.name} looks tired and ready to make a friend!`;drawBattle()};
document.getElementById('battleItem').onclick=()=>{document.getElementById('battleMsg').textContent=`You shared a crunchy snack. ${encounter.name} seems to like you!`;if(encounter)encounter.hp=Math.max(1,encounter.hp-2);if(encounter)document.getElementById('enemyHp').style.width=(encounter.hp/encounter.maxHp*100)+'%'};document.getElementById('runBtn').onclick=()=>{if(encounter)closeEncounter('You tiptoe back into the tall grass.');};
function updateUI(){document.getElementById('dexCount').textContent=seen.size;document.getElementById('teamCount').textContent=`${team.length} / 6`;let list=document.getElementById('teamList');if(!team.length)list.innerHTML='<div class="empty-team">Your journey is just beginning.<br>Wild friends are waiting in the grass ✿</div>';else list.innerHTML=team.slice(0,6).map((c,i)=>`<div class="creature-row"><div class="creature-art"><canvas width="40" height="40" data-creature="${i}"></canvas></div><div class="creature-info"><div class="creature-name">${c.name}</div><div class="creature-type">${c.type}</div></div><span class="creature-lvl">Lv.${c.level||1}</span></div>`).join('');team.forEach((c,i)=>{let cv=list.querySelector(`[data-creature="${i}"]`);if(cv){let g=cv.getContext('2d');g.imageSmoothingEnabled=false;drawMini(g,c,20,20)}});let pct=Math.min(100,seen.size/3*100);document.getElementById('questBar').style.width=pct+'%';document.getElementById('questCount').textContent=`${Math.min(seen.size,3)} / 3`}
function drawMini(g,c,x,y){g.save();g.translate(x,y);g.fillStyle=c.color;g.fillRect(-7,-5,14,12);g.fillRect(-5,-9,4,5);g.fillRect(2,-9,4,5);g.fillStyle=c.accent;g.fillRect(-5,-6,3,3);g.fillRect(3,-6,3,3);g.fillStyle='#283c34';g.fillRect(-4,-2,2,2);g.fillRect(3,-2,2,2);g.restore()}
function showBook(){let grid=document.getElementById('bookGrid');grid.innerHTML=species.map(c=>`<div class="bookcell ${seen.has(c.name)?'':'unknown'}"><canvas width="44" height="42"></canvas><strong>${seen.has(c.name)?c.name:'???'}</strong><small>${seen.has(c.name)?c.type:'not yet found'}</small></div>`).join('');grid.querySelectorAll('canvas').forEach((cv,i)=>{if(seen.has(species[i].name)){let g=cv.getContext('2d');g.imageSmoothingEnabled=false;drawMini(g,species[i],22,21)}});document.getElementById('bookOverlay').classList.add('open')}
function closeOverlays(){document.querySelectorAll('.overlay').forEach(o=>o.classList.remove('open'))}document.getElementById('navDex').onclick=showBook;document.getElementById('navExplore').onclick=closeOverlays;document.getElementById('closeBook').onclick=closeOverlays;document.getElementById('bookOverlay').onclick=e=>{if(e.target.id==='bookOverlay')closeOverlays()};document.getElementById('battleOverlay').onclick=e=>{if(e.target.id==='battleOverlay')return};updateUI();render();
</script></body></html>

